const PredictionPage = () => {
    const [inputData, setInputData] = useState(Array(32).fill(""));  // 32 features
    const [modelType, setModelType] = useState("rf");
    const [result, setResult] = useState(null);
    const [loading, setLoading] = useState(false);
  
    const handleChange = (index, value) => {
      const newData = [...inputData];
      newData[index] = value;
      setInputData(newData);
    };
  
    const handleSubmit = async (e) => {
      e.preventDefault();
      const values = inputData.map(Number);
      if (values.some(isNaN)) {
        alert("All fields must be filled with numbers");
        return;
      }
  
      setLoading(true);
      try {
        const res = await axios.post("http://localhost:5000/predict", {
          inputData: values,
          modelType,
        });
        setResult(res.data.prediction === 1 ? "Alzheimer's Detected" : "No Alzheimer's Detected");
      } catch (error) {
        console.error(error);
        setResult("Prediction failed.");
      } finally {
        setLoading(false);
      }
    };
  
    return (
      <div style={{ padding: "2rem", fontFamily: "Arial" }}>
        <h2>Alzheimer's Disease Prediction</h2>
        <form onSubmit={handleSubmit}>
          {inputData.map((val, idx) => (
            <div key={idx}>
              <label>
                Feature {idx + 1}:{" "}
                <input
                  type="number"
                  value={val}
                  onChange={(e) => handleChange(idx, e.target.value)}
                  required
                />
              </label>
            </div>
          ))}
  
          <div>
            <label>Select Model: </label>
            <select value={modelType} onChange={(e) => setModelType(e.target.value)}>
              <option value="rf">Random Forest</option>
              <option value="svm">SVM</option>
              <option value="cnn">CNN</option>
            </select>
          </div>
  
          <button type="submit" disabled={loading}>
            {loading ? "Predicting..." : "Predict"}
          </button>
        </form>
  
        {result && (
          <div style={{ marginTop: "1rem", fontWeight: "bold" }}>
            Prediction Result: {result}
          </div>
        )}
      </div>
    );
  };
